using System;using System.Collections.Generic;using System.Linq;namespace Mapping{    internal class MPWMapCreater    {        private double radius;        private int shotRows;        private int shotColumns;        private double shotStepX;        private double shotStepY;        private int rowsInShot;        private int columnsInShot;        private double[] dieSizeXs;        private double[] dieSizeYs;        private double offsetX = 0;        private double offsetY = 6167;        public MPWMapCreater()        {        }        public MapData Create(double radius, int shotRows, int shotColumns, double shotStepX, double shotStepY,            int rowsInShot, int columnsInShot, double[] dieSizeXs, double[] dieSizeYs, double offsetX, double offsetY,            BinCollection shotBins)        {            if (radius <= 0)            {                throw new ArgumentOutOfRangeException("radius must been greater than 0.");            }            if (shotRows <= 0)            {                throw new ArgumentOutOfRangeException("shotRows must been greater than 0.");            }            if (shotColumns <= 0)            {                throw new ArgumentOutOfRangeException("shotColumns must been greater than 0.");            }            if (shotStepX <= 0)            {                throw new ArgumentOutOfRangeException("shotStepX must been greater than 0.");            }            if (shotStepY <= 0)            {                throw new ArgumentOutOfRangeException("shotStepY must been greater than 0.");            }            if (rowsInShot <= 0)            {                throw new ArgumentOutOfRangeException("rowsInShot must been greater than 0.");            }            if (columnsInShot <= 0)            {                throw new ArgumentOutOfRangeException("columnsInShot must been greater than 0.");            }            if (dieSizeXs == null)            {                throw new ArgumentNullException(nameof(dieSizeXs));            }            if (dieSizeYs == null)            {                throw new ArgumentNullException(nameof(dieSizeYs));            }            if (shotBins == null)            {                throw new ArgumentNullException(nameof(shotBins));            }            if (radius <= shotStepY)            {                throw new ArgumentException("Invalid input parameter.");            }            if (radius <= shotStepX)            {                throw new ArgumentException("Invalid input parameter.");            }            if (rowsInShot != dieSizeYs.Length)            {                throw new ArgumentException("Invalid input parameter.");            }            if (columnsInShot != dieSizeXs.Length)            {                throw new ArgumentException("Invalid input parameter.");            }            if (shotBins.Count < (rowsInShot * columnsInShot))            {                throw new ArgumentException("Invalid input parameter.");            }            double shotX = 0;            foreach (var x in dieSizeXs)            {                shotX += x;            }            if (shotX > shotStepX)            {                throw new ArgumentException("Invalid input parameter.");            }            double shotY = 0;            foreach (var y in dieSizeYs)            {                shotY += y;            }            if (shotY > shotStepY)            {                throw new ArgumentException("Invalid input parameter.");            }            this.radius = radius;            this.shotRows = shotRows;            this.shotColumns = shotColumns;            this.shotStepX = shotStepX;            this.shotStepY = shotStepY;            this.rowsInShot = rowsInShot;            this.columnsInShot = columnsInShot;            this.dieSizeXs = dieSizeXs;            this.dieSizeYs = dieSizeYs;            this.offsetX = offsetX;            this.offsetY = offsetY;            var mapData = new MapData();            mapData.BlockRows = shotRows;            mapData.BlockColumns = shotColumns;            mapData.Rows = rowsInShot;            mapData.Columns = columnsInShot;            mapData.NullBin = Bin.CreateNullBin('.');            mapData.EmptyBin = Bin.CreateEmptyBin('-');            mapData.SubstrateID = DateTime.Now.ToString("yyyy-MM-dd_HH:mm:ss");            mapData.BinCodes = new BinCode[shotRows, shotColumns, rowsInShot, columnsInShot];            mapData.Bins = new BinCollection();            mapData.ShotBins = new Bin[rowsInShot, columnsInShot];            for (int i = 0; i < shotBins.Count; i++)            {                int r = i / columnsInShot;                int c = i - r * columnsInShot;                mapData.ShotBins[r, c] = shotBins[i];                if (!mapData.Bins.Exists(x => x.Code == shotBins[i].Code))                {                    mapData.Bins.Add(shotBins[i]);                }            }            double left = 0;            double top = 0;            double right = 0;            double bottom = 0;            for (int sr = 0; sr < shotRows; sr++)            {                for (int sc = 0; sc < shotColumns; sc++)                {                    for (int r = 0; r < rowsInShot; r++)                    {                        for (int c = 0; c < columnsInShot; c++)                        {                            this.GetDieBoundary(sr, sc, r, c, ref left, ref top, ref right, ref bottom);                            if (this.IsRectInCircle(top, left, bottom, right))                            {                                mapData.BinCodes[sr, sc, r, c] = mapData.ShotBins[r, c].Code;                            }                            else                            {                                mapData.BinCodes[sr, sc, r, c] = mapData.NullBin.Code;                            }                        }                    }                }            }            return mapData;        }        private bool IsRectInCircle(double top, double left, double bottom, double right)        {            double d1 = System.Math.Sqrt(top * top + left * left);            if (d1 > this.radius)            {                return false;            }            double d2 = System.Math.Sqrt(top * top + right * right);            if (d2 > this.radius)            {                return false;            }            double d3 = System.Math.Sqrt(bottom * bottom + left * left);            if (d3 > this.radius)            {                return false;            }            double d4 = System.Math.Sqrt(bottom * bottom + right * right);            if (d4 > this.radius)            {                return false;            }            return true;        }        private void GetShotCenterPos(int shotRow, int shotColumn, ref double centerX, ref double centerY)        {            // center shot row            double csr = this.shotRows * 0.5 - 0.5;            // center shot column            double csc = this.shotColumns * 0.5 - 0.5;            centerX = (shotColumn - csc) * this.shotStepX + this.offsetX;            centerY = (csr - shotRow) * this.shotStepY + this.offsetY;        }        private void GetDieCenterPos(int shotRow, int shotColumn, int rowInShot, int columnInShot, ref double centerX, ref double centerY)        {            double x = 0;            double y = 0;            double r = 0, t = 0;            this.GetDieBoundary(shotRow, shotColumn, rowInShot, columnInShot, ref x, ref y, ref r, ref t);            centerX = x;            centerY = y;        }        private void GetDieBoundary(int shotRow, int shotColumn, int rowInShot, int columnInShot, ref double left, ref double top, ref double right, ref double bottom)        {            // shot center            double scX = 0;            double scY = 0;            this.GetShotCenterPos(shotRow, shotColumn, ref scX, ref scY);            // shot top/left            double scLeft = scX - this.shotStepX * 0.5;            double scTop = scY + this.shotStepY * 0.5;            double x = scLeft;            double y = scTop;            for (int r = 0; r < rowInShot; r++)            {                y -= this.dieSizeYs[r];            }            for (int c = 0; c < columnInShot; c++)            {                x += this.dieSizeXs[c];            }            left = x;            top = y;            right = left + this.dieSizeXs[columnInShot];            bottom = top - this.dieSizeYs[rowInShot];        }        public sealed class BinEqualityComparer : IEqualityComparer<Bin>        {            public bool Equals(Bin x, Bin y)            {                return x == y;            }            public int GetHashCode(Bin obj)            {                return obj.GetHashCode();            }        }    }}